PATCH = "diff --git a/__tests__/codex-plugin.test.ts b/__tests__/codex-plugin.test.ts\nindex 85027eb..444bb64 100644\n--- a/__tests__/codex-plugin.test.ts\n+++ b/__tests__/codex-plugin.test.ts\n@@ -15,7 +15,7 @@\n import { describe, it, expect, beforeAll, afterAll } from \"bun:test\";\n import { readFile, mkdir, rm, writeFile } from \"fs/promises\";\n import { join } from \"path\";\n-import { existsSync } from \"fs\";\n+import { existsSync, mkdtempSync } from \"fs\";\n import { tmpdir } from \"os\";\n import {\n   isCodexPluginMarketplace,\n@@ -28,7 +28,7 @@ import type { Skill } from \"../src/cli/types\";\n \n // ── Test directories ──────────────────────────────────────────────────────────\n \n-const TEST_HOME = join(tmpdir(), `arra-codex-plugin-${Date.now()}`);\n+const TEST_HOME = mkdtempSync(join(tmpdir(), \"arra-codex-plugin-\"));\n const CODEX_DIR = join(TEST_HOME, \".codex\");\n const CONFIG_PATH = join(CODEX_DIR, \"config.toml\");\n const MARKETPLACE_DIR = join(\n@@ -89,7 +89,7 @@ describe(\"isCodexPluginMarketplace\", () => {\n   });\n \n   it(\"returns false for a home dir without config.toml\", () => {\n-    expect(isCodexPluginMarketplace(join(tmpdir(), \"nonexistent-home-99999\"))).toBe(false);\n+    expect(isCodexPluginMarketplace(join(TEST_HOME, \"missing-home\"))).toBe(false);\n   });\n });\n \n@@ -338,3 +338,42 @@ describe(\"installCodexPluginMarketplace (real skills)\", () => {\n     }\n   });\n });\n+\n+// Reinstalling across a Codex version change must not leave stale descriptors.\n+describe(\"Codex marketplace format migration\", () => {\n+  const marketplaceDir = join(TEST_HOME, \"migration-marketplace\");\n+  const configPath = join(TEST_HOME, \"migration-config.toml\");\n+  const skill: Skill = {\n+    name: \"migration-test\",\n+    description: \"Checks migrated skill content\",\n+    path: join(TEST_HOME, \"source-skill\"),\n+  };\n+\n+  it(\"migrates V1 to V2 and back while retaining skill content\", async () => {\n+    await mkdir(skill.path, { recursive: true });\n+    await writeFile(join(skill.path, \"SKILL.md\"), \"# Migration skill\\n\");\n+    await writeFile(configPath, \"\");\n+\n+    const install = (codexVersion: string) => installCodexPluginMarketplace(\n+      [skill], \"26.5.14\", \"no-shell\", { marketplaceDir, configPath, codexVersion }\n+    );\n+    const pluginDir = join(marketplaceDir, \"plugins\", skill.name);\n+    await install(\"0.128.0\");\n+    expect(existsSync(join(pluginDir, \"plugin.toml\"))).toBe(true);\n+    expect(await readFile(join(pluginDir, \"prompt.md\"), \"utf-8\")).toBe(\"# Migration skill\\n\");\n+\n+    await install(\"0.130.0\");\n+    expect(existsSync(join(marketplaceDir, \"manifest.toml\"))).toBe(false);\n+    expect(existsSync(join(pluginDir, \"plugin.toml\"))).toBe(false);\n+    expect(existsSync(join(pluginDir, \"prompt.md\"))).toBe(false);\n+    expect(await readFile(join(pluginDir, \"skills\", skill.name, \"SKILL.md\"), \"utf-8\"))\n+      .toBe(\"# Migration skill\\n\");\n+\n+    await install(\"0.128.0\");\n+    expect(existsSync(join(pluginDir, \".codex-plugin\"))).toBe(false);\n+    expect(existsSync(join(pluginDir, \"skills\"))).toBe(false);\n+    expect(await readFile(join(pluginDir, \"prompt.md\"), \"utf-8\")).toBe(\"# Migration skill\\n\");\n+    const config = await readFile(configPath, \"utf-8\");\n+    expect((config.match(/\\[plugins\\.\"migration-test@arra-oracle-skills\"\\]/g) || []).length).toBe(1);\n+  });\n+});\ndiff --git a/src/cli/installer.ts b/src/cli/installer.ts\nindex c8e1233..1e70a95 100644\n--- a/src/cli/installer.ts\n+++ b/src/cli/installer.ts\n@@ -75,10 +75,9 @@ export function isCodexV2Format(version: string | null): boolean {\n /**\n  * Install skills for Codex 0.128.0+ plugin marketplace.\n  *\n- * Creates:\n- *   <marketplaceDir>/manifest.toml\n- *   <marketplaceDir>/plugins/<skill>/plugin.toml\n- *   <marketplaceDir>/plugins/<skill>/prompt.md   (skill body)\n+ * For Codex < 0.130, creates manifest.toml and plugin.toml + prompt.md.\n+ * For Codex >= 0.130, creates .codex-plugin/plugin.json and\n+ * skills/<name>/SKILL.md per plugin. Removes obsolete format files on upgrade.\n  *\n  * Then updates ~/.codex/config.toml with:\n  *   [marketplaces.arra-oracle-skills]  source_type + source\n@@ -99,7 +98,10 @@ export async function installCodexPluginMarketplace(\n   await mkdirp(marketplaceDir, shellMode);\n \n   // ── 2. Write marketplace manifest (V1 only — Codex 0.130+ ignores it) ─────\n-  if (!v2) {\n+  if (v2) {\n+    // A prior install may have used V1; do not leave a misleading manifest.\n+    await rm(join(marketplaceDir, 'manifest.toml'), { force: true });\n+  } else {\n     const manifestContent = [\n       `name = \"arra-oracle-skills\"`,\n       `version = \"${version}\"`,\n@@ -118,6 +120,9 @@ export async function installCodexPluginMarketplace(\n     await mkdirp(skillPluginDir, shellMode);\n \n     if (v2) {\n+      // Clear files generated by the older layout when Codex auto-upgrades.\n+      await rm(join(skillPluginDir, 'plugin.toml'), { force: true });\n+      await rm(join(skillPluginDir, 'prompt.md'), { force: true });\n       // Codex 0.130+ format: .codex-plugin/plugin.json + skills/<name>/SKILL.md\n       const pluginMetaDir = join(skillPluginDir, '.codex-plugin');\n       await mkdirp(pluginMetaDir, shellMode);\n@@ -147,6 +152,9 @@ export async function installCodexPluginMarketplace(\n         }\n       }\n     } else {\n+      // Clear V2 metadata/content if an older Codex is installed again.\n+      await rm(join(skillPluginDir, '.codex-plugin'), { recursive: true, force: true });\n+      await rm(join(skillPluginDir, 'skills'), { recursive: true, force: true });\n       // Codex < 0.130 format: plugin.toml + prompt.md\n       const escapedDesc = skill.description.replace(/\\\\/g, '\\\\\\\\').replace(/\"/g, '\\\\\"');\n       const pluginToml = [\n"
